          contains('always()'),
          reason: 'hygiene must run even when legs skip',
        );
        expect(
          (sweep['permissions'] as YamlMap).containsKey('contents'),
          isTrue,
        );
        expect(sweep.toString(), contains('sweep_stale_drafts.sh'));
      },
    );

