import sys,re
hunks=[]
for l in sys.stdin:
    m=re.search(r'\+(\d+)(?:,(\d+))?',l)
    if m: hunks.append((int(m.group(1)), int(m.group(2) or 1)))
def inside(n): return any(a<=n<a+b for a,b in hunks)
for n in (1239,1240):
    print(n, 'in diff:', inside(n))
""}

